CREATE TABLE IF NOT EXISTS `workout_tasks` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `date` TEXT NOT NULL, `templateId` INTEGER NOT NULL, `name` TEXT NOT NULL, `category` TEXT NOT NULL, `bodyPart` TEXT NOT NULL, `equipment` TEXT NOT NULL, `sets` TEXT NOT NULL, `isCompleted` INTEGER NOT NULL, `target` TEXT NOT NULL, `actualWeight` TEXT NOT NULL, `isUnilateral` INTEGER NOT NULL, `logType` INTEGER NOT NULL, `imageUri` TEXT);
CREATE TABLE IF NOT EXISTS `exercise_templates` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `defaultTarget` TEXT NOT NULL, `category` TEXT NOT NULL, `bodyPart` TEXT NOT NULL, `equipment` TEXT NOT NULL, `isDeleted` INTEGER NOT NULL, `isUnilateral` INTEGER NOT NULL, `logType` INTEGER NOT NULL, `instruction` TEXT NOT NULL, `imageUri` TEXT, `animationUri` TEXT);
CREATE TABLE IF NOT EXISTS `schedule_config` (`dayOfWeek` INTEGER NOT NULL, `dayType` TEXT NOT NULL, PRIMARY KEY(`dayOfWeek`));
CREATE TABLE IF NOT EXISTS `weight_records` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `date` TEXT NOT NULL, `weight` REAL NOT NULL, `bodyFatKg` REAL, `skeletalMuscleKg` REAL, `bodyWaterPercentage` REAL, `waistCircumference` REAL, `hipCircumference` REAL);
CREATE TABLE IF NOT EXISTS `app_settings` (`id` INTEGER NOT NULL, `themeId` INTEGER NOT NULL, `languageCode` TEXT NOT NULL, `age` INTEGER NOT NULL, `height` REAL NOT NULL, `gender` INTEGER NOT NULL, `aiProvider` TEXT NOT NULL, `aiApiKey` TEXT NOT NULL, `aiModel` TEXT NOT NULL, `aiBaseUrl` TEXT NOT NULL, `useLocalAiCache` INTEGER NOT NULL, `maxHistoryLimit` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE IF NOT EXISTS `weekly_routine` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `dayOfWeek` INTEGER NOT NULL, `templateId` INTEGER NOT NULL, `name` TEXT NOT NULL, `target` TEXT NOT NULL, `category` TEXT NOT NULL, `bodyPart` TEXT NOT NULL, `equipment` TEXT NOT NULL, `isUnilateral` INTEGER NOT NULL, `logType` INTEGER NOT NULL, `imageUri` TEXT);
CREATE TABLE IF NOT EXISTS `ai_chat_history` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `timestamp` INTEGER NOT NULL, `role` TEXT NOT NULL, `content` TEXT NOT NULL, `userGoal` TEXT, `modelUsed` TEXT);
CREATE TABLE IF NOT EXISTS `ai_provider_configs` (`providerName` TEXT NOT NULL, `apiKey` TEXT NOT NULL, `model` TEXT NOT NULL, `baseUrl` TEXT NOT NULL, PRIMARY KEY(`providerName`));
CREATE TABLE IF NOT EXISTS `ai_memory` (`id` INTEGER NOT NULL, `longTermContext` TEXT NOT NULL, `lastSyncTime` INTEGER NOT NULL, PRIMARY KEY(`id`));